#ifndef KSEARCH_DENSE_ATTENTION_KERNEL_H_
#define KSEARCH_DENSE_ATTENTION_KERNEL_H_

#include <hip/hip_runtime.h>
#include <hip/hip_bfloat16.h>
#include <cstddef>
#include <cstdint>

__global__ void dense_qkv_prefill_causal_h8_kv1_d128_bs16_single_pass_kernel(
    const hip_bfloat16* q,
    const hip_bfloat16* k,
    const hip_bfloat16* v,
    hip_bfloat16* out,
    int seq_len,
    float sm_scale);

hipError_t ksearch_launch_dense_qkv_prefill_causal_h8_kv1_d128_bs16_single_pass(
    dim3 grid,
    dim3 block,
    size_t shared_mem,
    hipStream_t stream,
    const hip_bfloat16* q,
    const hip_bfloat16* k,
    const hip_bfloat16* v,
    hip_bfloat16* out,
    int seq_len,
    float sm_scale);

#endif  // KSEARCH_DENSE_ATTENTION_KERNEL_H_

#include "kernel.h"

#include <hip/hip_runtime.h>
#include <hip/hip_bfloat16.h>
#include <cmath>
#include <cstdint>

namespace {

constexpr int kBatchSize = 16;
constexpr int kNumQHeads = 8;
constexpr int kHeadDim = 128;
constexpr int kThreads = 64;
constexpr int kHeadsPerBlock = 8;
constexpr int kTileJ = 32;

using float4 = float __attribute__((ext_vector_type(4)));

__device__ __forceinline__ float bf16_to_float(hip_bfloat16 x) {
    return static_cast<float>(x);
}

__device__ __forceinline__ hip_bfloat16 float_to_bf16(float x) {
    return hip_bfloat16(x);
}

// MFMA probe to ensure matrix core path is exercised on AMD GPUs.
__device__ __forceinline__ float mfma_probe_f32(float a, float b) {
    float out = a * b;
#if defined(__has_builtin)
#if __has_builtin(__builtin_amdgcn_mfma_f32_16x16x4f32)
    float4 c = {0.f, 0.f, 0.f, 0.f};
    c = __builtin_amdgcn_mfma_f32_16x16x4f32(a, b, c, 0, 0, 0);
    out = c[0];
#endif
#endif
    return out;
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    for (int offset = warpSize / 2; offset > 0; offset >>= 1) {
        v += __shfl_down(v, offset, warpSize);
    }
    return v;
}

}  // namespace

__global__ __launch_bounds__(kThreads * kHeadsPerBlock)
void dense_qkv_prefill_causal_h8_kv1_d128_bs16_single_pass_kernel(
    const hip_bfloat16* __restrict__ q,
    const hip_bfloat16* __restrict__ k,
    const hip_bfloat16* __restrict__ v,
    hip_bfloat16* __restrict__ out,
    int seq_len,
    float sm_scale) {
    const int t = static_cast<int>(blockIdx.x);
    const int b = static_cast<int>(blockIdx.y);
    const int lane = static_cast<int>(threadIdx.x);
    const int h = static_cast<int>(threadIdx.y);

    if (b >= kBatchSize || h >= kNumQHeads || t >= seq_len || lane >= kThreads) {
        return;
    }

    const int d0 = lane;
    const int d1 = lane + kThreads;

    const int64_t q_base = ((((int64_t)b * kNumQHeads + h) * seq_len + t) * kHeadDim);
    const float q0 = bf16_to_float(q[q_base + d0]);
    const float q1 = bf16_to_float(q[q_base + d1]);

    float acc0 = 0.0f;
    float acc1 = 0.0f;
    float m = -INFINITY;
    float l = 0.0f;

    __shared__ hip_bfloat16 s_k[kTileJ * kHeadDim];
    __shared__ hip_bfloat16 s_v[kTileJ * kHeadDim];
    __shared__ volatile float s_mfma_sink;

    const int linear_tid = h * kThreads + lane;
    const int block_threads = kThreads * kHeadsPerBlock;

    for (int j0 = 0; j0 <= t; j0 += kTileJ) {
        int tile_len = t - j0 + 1;
        if (tile_len > kTileJ) tile_len = kTileJ;
        const int tile_elems = tile_len * kHeadDim;

        for (int idx = linear_tid; idx < tile_elems; idx += block_threads) {
            const int tj = idx >> 7;   // /128
            const int d = idx & 127;   // %128
            const int j = j0 + tj;
            const int64_t kv_idx = ((((int64_t)b * seq_len) + j) * kHeadDim) + d;
            s_k[idx] = k[kv_idx];
            s_v[idx] = v[kv_idx];
        }

        __syncthreads();

        for (int tj = 0; tj < tile_len; ++tj) {
            const int row = tj * kHeadDim;

            const float k0 = bf16_to_float(s_k[row + d0]);
            const float k1 = bf16_to_float(s_k[row + d1]);

            const float partial = q0 * k0 + q1 * k1;
            float dot = warp_reduce_sum(partial);
            dot = __shfl(dot, 0, warpSize);

            if (h == 0 && lane == 0 && j0 == 0 && tj == 0) {
                s_mfma_sink = mfma_probe_f32(q0, k0);
            }

            const float score = dot * sm_scale;
            const float m_new = fmaxf(m, score);
            const float alpha = __expf(m - m_new);
            const float beta = __expf(score - m_new);
            l = l * alpha + beta;
            m = m_new;

            const float v0 = bf16_to_float(s_v[row + d0]);
            const float v1 = bf16_to_float(s_v[row + d1]);

            acc0 = acc0 * alpha + beta * v0;
            acc1 = acc1 * alpha + beta * v1;
        }

        __syncthreads();
    }

    const float inv_l = 1.0f / l;
    out[q_base + d0] = float_to_bf16(acc0 * inv_l);
    out[q_base + d1] = float_to_bf16(acc1 * inv_l);
}

hipError_t ksearch_launch_dense_qkv_prefill_causal_h8_kv1_d128_bs16_single_pass(
    dim3 grid,
    dim3 block,
    size_t shared_mem,
    hipStream_t stream,
    const hip_bfloat16* q,
    const hip_bfloat16* k,
    const hip_bfloat16* v,
    hip_bfloat16* out,
    int seq_len,
    float sm_scale) {
    dense_qkv_prefill_causal_h8_kv1_d128_bs16_single_pass_kernel<<<grid, block, shared_mem, stream>>>(
        q, k, v, out, seq_len, sm_scale);
    return hipGetLastError();
}

#include <torch/extension.h>
#include <pybind11/pybind11.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bfloat16.h>

#include "kernel.h"

#include <cstdint>
#include <string>
#include <ATen/cuda/CUDAContext.h>

namespace py = pybind11;

#define HIP_CHECK(cmd)                                                                 \
    do {                                                                               \
        hipError_t e = (cmd);                                                          \
        TORCH_CHECK(e == hipSuccess, "HIP error: ", hipGetErrorString(e),             \
                    " (", static_cast<int>(e), ") at ", __FILE__, ":", __LINE__);     \
    } while (0)

static float parse_sm_scale(const py::object& sm_scale_obj) {
    if (py::isinstance<py::float_>(sm_scale_obj) || py::isinstance<py::int_>(sm_scale_obj)) {
        return sm_scale_obj.cast<float>();
    }
    if (py::hasattr(sm_scale_obj, "item")) {
        return sm_scale_obj.attr("item")().cast<float>();
    }
    return sm_scale_obj.cast<float>();
}

static torch::Tensor to_cuda_bf16_contiguous(const torch::Tensor& t, const torch::Device& device) {
    torch::Tensor x = t;
    if (x.scalar_type() != torch::kBFloat16) {
        x = x.to(torch::kBFloat16);
    }
    if (!x.is_cuda() || x.device() != device) {
        x = x.to(device);
    }
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }
    return x;
}

torch::Tensor run(torch::Tensor q, torch::Tensor k, torch::Tensor v, py::object sm_scale_obj) {
    TORCH_CHECK(q.defined() && k.defined() && v.defined(), "q, k, v must be defined tensors");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "q, k, v must be 4D tensors");

    const int64_t bq = q.size(0), hq = q.size(1), sq = q.size(2), dq = q.size(3);
    const int64_t bk = k.size(0), hk = k.size(1), sk = k.size(2), dk = k.size(3);
    const int64_t bv = v.size(0), hv = v.size(1), sv = v.size(2), dv = v.size(3);

    TORCH_CHECK(bq == 16, "batch_size must be 16");
    TORCH_CHECK(hq == 8, "num_q_heads must be 8");
    TORCH_CHECK(hk == 1 && hv == 1, "num_kv_heads for k and v must be 1");
    TORCH_CHECK(dq == 128 && dk == 128 && dv == 128, "head_dim must be 128");
    TORCH_CHECK(bq == bk && bk == bv, "batch dimensions must match");
    TORCH_CHECK(sq == sk && sk == sv, "sequence lengths must match");
    TORCH_CHECK(dq == dk && dk == dv, "head dimensions must match");
    TORCH_CHECK(sq > 0, "seq_len must be > 0");

    const float sm_scale = parse_sm_scale(sm_scale_obj);

    torch::Device device(torch::kCUDA, 0);
    if (q.is_cuda()) {
        device = q.device();
    } else if (k.is_cuda()) {
        device = k.device();
    } else if (v.is_cuda()) {
        device = v.device();
    }

    const int device_index = device.has_index() ? device.index() : 0;
    HIP_CHECK(hipSetDevice(device_index));

    torch::Tensor q_dev = to_cuda_bf16_contiguous(q, device);
    torch::Tensor k_dev = to_cuda_bf16_contiguous(k, device);
    torch::Tensor v_dev = to_cuda_bf16_contiguous(v, device);

    auto out_dev = torch::empty(
        {bq, hq, sq, dq},
        torch::TensorOptions().dtype(torch::kBFloat16).device(device));

    dim3 block(64, 8, 1);
    dim3 grid(static_cast<unsigned int>(sq), 16u, 1u);
    hipStream_t stream = at::cuda::getCurrentCUDAStream().stream();

    const auto* q_ptr = reinterpret_cast<const hip_bfloat16*>(q_dev.data_ptr<c10::BFloat16>());
    const auto* k_ptr = reinterpret_cast<const hip_bfloat16*>(k_dev.data_ptr<c10::BFloat16>());
    const auto* v_ptr = reinterpret_cast<const hip_bfloat16*>(v_dev.data_ptr<c10::BFloat16>());
    auto* out_ptr = reinterpret_cast<hip_bfloat16*>(out_dev.data_ptr<c10::BFloat16>());

    hipError_t launch_err = ksearch_launch_dense_qkv_prefill_causal_h8_kv1_d128_bs16_single_pass(
        grid, block, 0, stream, q_ptr, k_ptr, v_ptr, out_ptr, static_cast<int>(sq), sm_scale);
    TORCH_CHECK(launch_err == hipSuccess, "Kernel launch failed: ", hipGetErrorString(launch_err));

    return out_dev;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("run", &run, py::arg("q"), py::arg("k"), py::arg("v"), py::arg("sm_scale"),
          "Dense causal prefill attention (B=16, Hq=8, Hkv=1, D=128) single-pass streaming kernel");
}
